import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [o for _, o in history]
    me = [m for m, _ in history]
    op_last = opp[-1]
    my_last = me[-1]

    op_c = 0
    op_d = 0
    for x in opp:
        if x == 'C':
            op_c += 1
        else:
            op_d += 1

    my_c = 0
    my_d = 0
    for x in me:
        if x == 'C':
            my_c += 1
        else:
            my_d += 1

    # Detect opponents that never cooperate: stop wasting cooperation.
    if n >= 4 and op_c == 0:
        return 'D'

    # Defect against persistent defection.
    if n >= 6 and op_d * 4 >= n * 3:
        return 'D'

    # Endgame: exploit a cooperative opponent.
    remaining = 100 - n
    if remaining <= 3:
        if op_c * 2 >= n:
            return 'D'
        return 'D'

    # If opponent is extremely cooperative, exploit late but maintain cooperation early.
    if n >= 20 and op_c * 10 >= n * 9:
        if remaining <= 12:
            return 'D'

    # Tit-for-tat core with forgiveness.
    if op_last == 'D':
        # Recent opponent defections
        recent = opp[-5:]
        recent_d = 0
        for x in recent:
            if x == 'D':
                recent_d += 1

        # If they've been mostly cooperative overall, forgive once in a while.
        if op_d * 5 <= n:
            return 'C'

        # If recent mostly cooperative, forgive.
        if recent_d <= 1:
            return 'C'

        # If we defected last turn too, try to break the DD cycle.
        if my_last == 'D':
            # If opponent has defected a lot recently, keep defecting.
            if recent_d >= 3:
                return 'D'
            return 'C'

        return 'D'
    else:
        # Opponent cooperated.
        # If they're highly cooperative, keep cooperating to preserve mutual CC.
        if op_d * 5 <= n:
            return 'C'

        # If we've been defecting repeatedly against a cooperator, exploit lightly.
        recent_me = me[-3:]
        recent_op = opp[-3:]
        if len(recent_me) == 3 and len(recent_op) == 3:
            me_all_d = True
            op_all_c = True
            for x in recent_me:
                if x != 'D':
                    me_all_d = False
                    break
            for x in recent_op:
                if x != 'C':
                    op_all_c = False
                    break
            if me_all_d and op_all_c:
                return 'D'

        return 'C'
